// Both answers matter. A context.Canceled that arose without a signal is a
// genuine failure and must be reported as one rather than masquerading as a
// user abort. And a SIGTERM from a supervisor must exit 143 rather than
// impersonating a Ctrl-C's 130.
package procsignal

import (
	"os"
	"sync/atomic"
)

// holder wraps the stored signal so atomic.Value always observes one concrete
// type. Storing differing concrete types (or nil) into an atomic.Value panics;
// wrapping avoids both.
type holder struct{ sig os.Signal }

var caught atomic.Value // stores holder

// Store records sig as the signal that initiated shutdown. Safe for concurrent
// use; last writer wins, which is fine because every caller stores a genuine
// terminating signal.
func Store(sig os.Signal) {
	caught.Store(holder{sig: sig})
}

// Load returns the recorded terminating signal, or nil if none was recorded.
func Load() os.Signal {
	if h, ok := caught.Load().(holder); ok {
		return h.sig
	}
	return nil
}

// Reset clears the recorded signal. It exists for tests that need a clean
// slate; production code never clears it, because the process is on its way
// out by the time anything is recorded.
func Reset() {
	caught.Store(holder{})
}

package procsignal

import (
	"os"
	"syscall"
	"testing"

	"github.com/stretchr/testify/require"
)

// These tests mutate the package-global recorded signal, so they must not run
// in parallel with each other.

func TestLoadReportsTheStoredSignal(t *testing.T) {
	Reset()
	require.Nil(t, Load(), "no signal recorded yet")

	Store(os.Interrupt)
	require.Equal(t, os.Interrupt, Load())

	// A different concrete signal type must not panic the atomic store, and
	// must win: the last signal observed is the one that terminates us.
	Store(syscall.SIGTERM)
	require.Equal(t, os.Signal(syscall.SIGTERM), Load())
}

func TestResetClearsTheStoredSignal(t *testing.T) {
	Store(os.Interrupt)
	Reset()
	require.Nil(t, Load())
}

// Package versioninfo reports which harnaas build is running.
//
// Version and Commit are stamped by goreleaser via ldflags on a release build.
// Every other build — `mise run build`, `go install
// github.com/harnaas/harnaas/cmd/harnaas@<version>`, a plain `go build` —
// carries no stamp, so Load recovers what it can from Go's embedded build
// information and the binary still self-reports something truthful.
package versioninfo

import (
	"runtime/debug"
	"strings"
)

// The placeholders Load treats as "unstamped". A build that carries a real
// stamp keeps it: an explicit stamp always beats the embedded build info.
const (
	devVersion   = "dev"
	unknownComit = "unknown"
)

// Version and Commit identify the running harnaas build. goreleaser overwrites
// both through -X ldflags; see .goreleaser.yaml.
var (
	Version = devVersion
	Commit  = unknownComit
)

// Load fills Version and Commit from the binary's embedded build information
// where ldflags left them at their defaults. Call it once from main, before
// anything reads either variable.
func Load() {
	info, ok := debug.ReadBuildInfo()
	Version, Commit = resolve(Version, Commit, info, ok)
}

// resolve is Load's pure core, so the precedence rules are testable without a
// real build. A module install (`@<version>`) carries the version as
// info.Main.Version; a local build reports "(devel)" there but records the
// commit under vcs.revision. Go already marks a dirty tree with a "+dirty"
// suffix on the version, so there is no need to read vcs.modified.
func resolve(version, commit string, info *debug.BuildInfo, ok bool) (string, string) {
	if version != devVersion || !ok || info == nil {
		return version, commit
	}

	if v := info.Main.Version; v != "" && v != "(devel)" {
		version = strings.TrimPrefix(v, "v") // match goreleaser's {{.Version}}
	}
	if commit == unknownComit {
		for _, setting := range info.Settings {
			if setting.Key == "vcs.revision" && setting.Value != "" {
				commit = setting.Value
			}
		}
	}

	return version, commit
}

